using System.Security.Claims;
using FIXIT.Domain.Entities;
using FIXIT.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace FIXIT.API.Controllers;
[ApiController,Route("api/bookings/{bookingId:int}/photos"),Authorize]
public class BookingPhotosController(FIXITDbContext db,IWebHostEnvironment env):ControllerBase
{
 string UserId=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 [HttpGet] public async Task<IActionResult> List(int bookingId){var b=await db.Bookings.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==bookingId);if(b is null)return NotFound();if(b.CustomerId!=UserId&&b.TechnicianId!=UserId&&!User.IsInRole("Administrator"))return Forbid();return Ok(await db.BookingPhotos.AsNoTracking().Where(p=>p.BookingId==bookingId).Select(p=>new{p.Id,p.Phase,p.ContentType,p.UploadedAt,p.UploadedById}).ToListAsync());}
 [HttpPost,RequestSizeLimit(6_000_000)] public async Task<IActionResult> Upload(int bookingId,IFormFile file,[FromForm]string phase,[FromForm]bool customerConsent=false){var b=await db.Bookings.SingleOrDefaultAsync(x=>x.Id==bookingId);if(b is null)return NotFound();var customer=b.CustomerId==UserId;var technician=b.TechnicianId==UserId;if(!customer&&!technician)return Forbid();if(phase is not ("before" or "after"))return BadRequest(new{message="Photo phase must be before or after."});if(technician&&!customerConsent)return BadRequest(new{message="Customer consent is required for technician photos."});if(file.Length is 0 or >5_000_000)return BadRequest(new{message="Choose an image smaller than 5 MB."});var header=new byte[12];await using(var s=file.OpenReadStream())await s.ReadExactlyAsync(header);var mime=Mime(header);if(mime is null)return BadRequest(new{message="Only JPEG, PNG, and WebP images are accepted."});var folder=Path.Combine(env.ContentRootPath,"PrivateUploads");Directory.CreateDirectory(folder);var key=$"{Guid.NewGuid():N}{(mime=="image/jpeg"?".jpg":mime=="image/png"?".png":".webp")}";var path=Path.Combine(folder,key);await using(var output=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))await file.CopyToAsync(output);var photo=new BookingPhoto{BookingId=bookingId,UploadedById=UserId,PrivateStorageKey=key,ContentType=mime,Phase=phase};db.BookingPhotos.Add(photo);await db.SaveChangesAsync();return Created($"/api/bookings/{bookingId}/photos/{photo.Id}",new{id=photo.Id,photo.Phase,photo.ContentType});}
 [HttpGet("{photoId:int}")] public async Task<IActionResult> Download(int bookingId,int photoId){var p=await db.BookingPhotos.Include(x=>x.Booking).SingleOrDefaultAsync(x=>x.Id==photoId&&x.BookingId==bookingId);if(p is null)return NotFound();if(p.Booking.CustomerId!=UserId&&p.Booking.TechnicianId!=UserId&&!User.IsInRole("Administrator"))return Forbid();var path=Path.Combine(env.ContentRootPath,"PrivateUploads",Path.GetFileName(p.PrivateStorageKey));if(!System.IO.File.Exists(path))return NotFound();return PhysicalFile(path,p.ContentType,$"fixit-{p.Phase}-{p.Id}",enableRangeProcessing:false);}
 static string? Mime(byte[] b){if(b.Length>=3&&b[0]==0xff&&b[1]==0xd8&&b[2]==0xff)return "image/jpeg";if(b.AsSpan().StartsWith(new byte[]{137,80,78,71,13,10,26,10}))return "image/png";if(b.Length>=12&&System.Text.Encoding.ASCII.GetString(b,0,4)=="RIFF"&&System.Text.Encoding.ASCII.GetString(b,8,4)=="WEBP")return "image/webp";return null;}
}
